  const alreadyMigrated = await temporary();
  await writeFile(path.join(alreadyMigrated, 'preferences.json'), JSON.stringify({
    schemaVersion: 2,
    entries: [{ key: 'muted', value: false, source: 'user' }],
    notifications: { badge: true },
    unrelated: 'kept',
